149|/**
150| * Skip all comments from the current pos resolving nested and multiline comments
151| * @param parser
152| * @return
153| */
154|static bool
155|ucl_skip_comments(struct ucl_parser *parser)
156|{
157|	struct ucl_chunk *chunk = parser->chunks;
158|	const unsigned char *p, *beg = NULL;
159|	int comments_nested = 0;
160|	bool quoted = false;
161|
162|	p = chunk->pos;
163|
164|start:
165|	if (chunk->remain > 0 && *p == '#') {
166|		if (parser->state != UCL_STATE_SCOMMENT &&
167|			parser->state != UCL_STATE_MCOMMENT) {
168|			beg = p;
169|
170|			while (p < chunk->end) {
171|				if (*p == '\n') {
172|					if (parser->flags & UCL_PARSER_SAVE_COMMENTS) {
173|						ucl_save_comment(parser, beg, p - beg);
174|						beg = NULL;
175|					}
176|
177|					ucl_chunk_skipc(chunk, p);
178|
179|					goto start;
180|				}
181|				ucl_chunk_skipc(chunk, p);
182|			}
183|		}
184|	}
185|	else if (chunk->remain >= 2 && *p == '/' && p[1] == '*') {
186|		beg = p;
187|		comments_nested++;
188|		ucl_chunk_skipc(chunk, p);
189|		ucl_chunk_skipc(chunk, p);
190|		while (p < chunk->end) {
191|			if (*p == '"' && *(p - 1) != '\\') {
192|				/* begin or end double-quoted string */
193|				quoted = !quoted;
194|				ucl_chunk_skipc(chunk, p);
195|			}
196|			else if (quoted) {
197|				/* quoted character */
198|				ucl_chunk_skipc(chunk, p);
199|			}
200|			else if (chunk->remain >= 2 && *p == '*' && p[1] == '/') {
201|				/* end of comment */
202|				ucl_chunk_skipc(chunk, p);
203|				ucl_chunk_skipc(chunk, p);
204|				comments_nested--;
205|				if (comments_nested == 0) {
206|					if (parser->flags & UCL_PARSER_SAVE_COMMENTS) {
207|						ucl_save_comment(parser, beg, p - beg + 1);
208|						beg = NULL;
209|					}
210|					goto start;
211|				}
212|			}
213|			else if (chunk->remain >= 2 && *p == '/' && p[1] == '*') {
214|				/* start of nested comment */
215|				comments_nested++;
216|				ucl_chunk_skipc(chunk, p);
217|				ucl_chunk_skipc(chunk, p);
218|			}
219|			else {
220|				/* anything else */
221|				ucl_chunk_skipc(chunk, p);
222|			}
223|		}
224|		if (comments_nested != 0) {
225|			ucl_set_err(parser, UCL_ENESTED,
226|						"unfinished multiline comment", &parser->err);
227|			return false;
228|		}
229|	}
230|
231|	if (beg && p > beg && (parser->flags & UCL_PARSER_SAVE_COMMENTS)) {
232|		ucl_save_comment(parser, beg, p - beg);
233|	}
234|
235|	return true;
