442|/**
443| * Expand a single variable
444| * @param parser
445| * @param ptr
446| * @param in_len
447| * @param dest
448| * @param out_len
449| * @return
450| */
451|static const char *
452|ucl_expand_single_variable(struct ucl_parser *parser, const char *ptr,
453|						   size_t in_len, unsigned char **dest, size_t out_len)
454|{
455|	unsigned char *d = *dest, *dst;
456|	const char *p = ptr + 1, *ret;
457|	struct ucl_variable *var;
458|	size_t dstlen;
459|	bool need_free = false;
460|	bool found = false;
461|	bool strict = false;
462|
463|	ret = ptr + 1;
464|	/* For the $ sign */
465|	in_len--;
466|
467|	if (*p == '$') {
468|		*d++ = *p++;
469|		*dest = d;
470|		return p;
471|	}
472|	else if (*p == '{') {
473|		p++;
474|		in_len--;
475|		strict = true;
476|		ret += 2;
477|	}
478|
479|	LL_FOREACH(parser->variables, var)
480|	{
481|		if (out_len >= var->value_len && in_len >= (var->var_len + (strict ? 1 : 0))) {
482|			if (memcmp(p, var->var, var->var_len) == 0) {
483|				if (!strict || p[var->var_len] == '}') {
484|					memcpy(d, var->value, var->value_len);
485|					ret += var->var_len;
486|					d += var->value_len;
487|					found = true;
488|					break;
489|				}
490|			}
491|		}
492|	}
493|
494|	if (!found) {
495|		if (strict && parser->var_handler != NULL) {
496|			dstlen = out_len;
497|
498|			if (parser->var_handler(p, in_len, &dst, &dstlen, &need_free,
499|									parser->var_data)) {
500|				if (dstlen > out_len) {
501|					/* We do not have enough space! */
502|					if (need_free) {
503|						free(dst);
504|					}
505|				}
506|				else {
507|					memcpy(d, dst, dstlen);
508|					ret += in_len;
509|					d += dstlen;
510|					found = true;
511|
512|					if (need_free) {
513|						free(dst);
514|					}
515|				}
516|			}
517|		}
518|
519|		/* Leave variable as is, in this case we use dest */
520|		if (!found) {
521|			if (strict && out_len >= 2) {
522|				/* Copy '${' */
523|				memcpy(d, ptr, 2);
524|				d += 2;
525|				ret--;
526|			}
527|			else {
528|				memcpy(d, ptr, 1);
529|				d++;
530|			}
531|		}
532|	}
533|
534|	*dest = d;
535|	return ret;
