631|/**
632| * Store or copy pointer to the trash stack
633| * @param parser parser object
634| * @param src src string
635| * @param dst destination buffer (trash stack pointer)
636| * @param dst_const const destination pointer (e.g. value of object)
637| * @param in_len input length
638| * @param max_len maximum accepted length, 0 for unlimited
639| * @param need_unescape need to unescape source (and copy it)
640| * @param need_lowercase need to lowercase value (and copy)
641| * @param need_expand need to expand variables (and copy as well)
642| * @param unescape_squote unescape single quoted string
643| * @return output length (excluding \0 symbol)
644| */
645|static inline ssize_t
646|ucl_copy_or_store_ptr(struct ucl_parser *parser,
647|					  const unsigned char *src, unsigned char **dst,
648|					  const char **dst_const, size_t in_len, uint64_t max_len,
649|					  bool need_unescape, bool need_lowercase, bool need_expand,
650|					  bool unescape_squote)
651|{
652|	ssize_t ret = -1, tret;
653|	unsigned char *tmp;
654|
655|	/*
656|	 * Checked before allocating: `in_len` comes straight from the input and
657|	 * is an upper bound on the result, as neither unescaping nor lowercasing
658|	 * can make a string longer.
659|	 */
660|	if (max_len > 0 && (uint64_t) in_len > max_len) {
661|		ucl_set_err(parser, UCL_ELIMIT, "string is too long", &parser->err);
662|
663|		return -1;
664|	}
665|
666|	if (need_unescape || need_lowercase ||
667|		(need_expand && parser->variables != NULL) ||
668|		!(parser->flags & UCL_PARSER_ZEROCOPY)) {
669|		/* Copy string */
670|		*dst = UCL_ALLOC(in_len + 1);
671|		if (*dst == NULL) {
672|			ucl_set_err(parser, UCL_EINTERNAL, "cannot allocate memory for a string",
673|						&parser->err);
674|			return -1;
675|		}
676|
677|		/*
678|		 * Charge what was actually allocated, not what the decoded string ends
679|		 * up being: unescaping shrinks the contents but keeps the buffer, so
680|		 * charging the decoded length would let escape-heavy input claim more
681|		 * memory than the budget accounts for.
682|		 */
683|		if (!ucl_parser_account_alloc(parser, (uint64_t) in_len + 1)) {
684|			return -1;
685|		}
686|
687|		if (need_lowercase) {
688|			ret = ucl_strlcpy_tolower(*dst, src, in_len + 1);
689|		}
690|		else {
691|			ret = ucl_strlcpy_unsafe(*dst, src, in_len + 1);
692|		}
693|
694|		if (need_unescape) {
695|			if (!unescape_squote) {
696|				ret = ucl_unescape_json_string(*dst, ret);
697|			}
698|			else {
699|				ret = ucl_unescape_squoted_string(*dst, ret);
700|			}
701|		}
702|
703|		if (need_expand) {
704|			tmp = *dst;
705|			tret = ret;
706|			ret = ucl_expand_variable(parser, dst, tmp, ret);
707|			if (*dst == NULL) {
708|				/* Nothing to expand */
709|				*dst = tmp;
710|				ret = tret;
711|			}
712|			else {
713|				/* Free unexpanded value */
714|				UCL_FREE(in_len + 1, tmp);
715|			}
716|
717|			/* Expansion is the one transform that can grow a string */
718|			if (max_len > 0 && ret > 0 && (uint64_t) ret > max_len) {
719|				ucl_set_err(parser, UCL_ELIMIT,
720|							"string is too long after variables expansion",
721|							&parser->err);
722|
723|				return -1;
724|			}
725|
726|			/* Charge whatever expansion added on top of the original buffer */
727|			if (ret > 0 && (uint64_t) ret > (uint64_t) in_len &&
728|				!ucl_parser_account_alloc(parser,
729|										  (uint64_t) ret - (uint64_t) in_len)) {
730|				return -1;
731|			}
732|		}
733|		*dst_const = *dst;
734|	}
735|	else {
736|		*dst_const = src;
737|		ret = in_len;
738|	}
739|
740|	return ret;
