788|						"cannot merge an object with an array",
789|						&parser->err);
790|
791|			return NULL;
792|		}
793|		nobj = obj;
794|		nobj->type = is_array ? UCL_ARRAY : UCL_OBJECT;
795|	}
796|
797|	if (!is_array) {
798|		if (nobj->value.ov == NULL) {
799|			nobj->value.ov = ucl_hash_create(parser->flags & UCL_PARSER_KEY_LOWERCASE);
800|			if (nobj->value.ov == NULL) {
