1204|/**
1205| * Parse quoted string with possible escapes
1206| * @param parser
1207| * @param chunk
1208| * @param need_unescape
1209| * @param ucl_escape
1210| * @param var_expand
1211| * @return true if a string has been parsed
1212| */
1213|static bool
1214|ucl_lex_json_string(struct ucl_parser *parser,
1215|					struct ucl_chunk *chunk,
1216|					bool *need_unescape,
1217|					bool *ucl_escape,
1218|					bool *var_expand)
