1337|static bool
1338|ucl_parser_append_elt(struct ucl_parser *parser, ucl_hash_t *cont,
1339|					  ucl_object_t *top,
1340|					  ucl_object_t *elt)
1341|{
1342|	ucl_object_t *nobj;
1343|
1344|	if ((parser->flags & UCL_PARSER_NO_IMPLICIT_ARRAYS) == 0) {
1345|		/* Implicit array */
1346|		top->flags |= UCL_OBJECT_MULTIVALUE;
1347|		DL_APPEND(top, elt);
1348|		parser->stack->obj->len++;
1349|	}
1350|	else {
1351|		if ((top->flags & UCL_OBJECT_MULTIVALUE) != 0) {
1352|			/* Just add to the explicit array */
1353|			if (!ucl_array_append(top, elt)) {
1354|				ucl_set_err(parser, UCL_EINTERNAL,
1355|							"cannot allocate memory for an array",
1356|							&parser->err);
1357|
1358|				return false;
1359|			}
1360|		}
1361|		else {
1362|			/*
1363|			 * Converting to an explicit array costs one more element, so it has
1364|			 * to be charged as well: otherwise a run of duplicate keys grows the
1365|			 * tree without ever touching the budget.
1366|			 */
1367|			if (!ucl_parser_account_node(parser)) {
1368|				return false;
1369|			}
1370|
1371|			nobj = ucl_object_typed_new(UCL_ARRAY);
1372|
1373|			if (nobj == NULL) {
1374|				ucl_set_err(parser, UCL_EINTERNAL,
1375|							"cannot allocate memory for an object",
1376|							&parser->err);
1377|
1378|				return false;
1379|			}
1380|
1381|			nobj->key = top->key;
1382|			nobj->keylen = top->keylen;
1383|			nobj->flags |= UCL_OBJECT_MULTIVALUE;
1384|
1385|			if (!ucl_array_append(nobj, top) ||
1386|				!ucl_array_append(nobj, elt)) {
1387|				/*
1388|				 * `top` is still owned by the container, so the half-built
1389|				 * array must be dropped without releasing what it holds.
1390|				 */
1391|				ucl_array_detach_elements(nobj);
1392|				ucl_object_unref(nobj);
1393|				ucl_set_err(parser, UCL_EINTERNAL,
1394|							"cannot allocate memory for an array",
1395|							&parser->err);
1396|
1397|				return false;
1398|			}
1399|
1400|			ucl_hash_replace(cont, top, nobj);
1401|		}
1402|	}
1403|
1404|	return true;
