1771|/**
1772| * Parse a cl string
1773| * @param parser
1774| * @param chunk
1775| * @param var_expand
1776| * @param need_unescape
1777| * @return true if a key has been parsed
1778| */
1779|static bool
1780|ucl_parse_string_value(struct ucl_parser *parser,
1781|					   struct ucl_chunk *chunk, bool *var_expand, bool *need_unescape)
1782|{
1783|	const unsigned char *p;
