1797|			braces[UCL_BRACE_FIGURE][0]++;
1798|		}
1799|		else if (*p == '}') {
1800|			braces[UCL_BRACE_FIGURE][1]++;
1801|			if (braces[UCL_BRACE_FIGURE][1] <= braces[UCL_BRACE_FIGURE][0]) {
1802|				/* This is not a termination symbol, continue */
1803|				ucl_chunk_skipc(chunk, p);
1804|				continue;
1805|			}
1806|		}
1807|		/* Skip pairs of square braces */
1808|		else if (*p == '[') {
1809|			braces[UCL_BRACE_SQUARE][0]++;
1810|		}
1811|		else if (*p == ']') {
1812|			braces[UCL_BRACE_SQUARE][1]++;
1813|			if (braces[UCL_BRACE_SQUARE][1] <= braces[UCL_BRACE_SQUARE][0]) {
1814|				/* This is not a termination symbol, continue */
1815|				ucl_chunk_skipc(chunk, p);
1816|				continue;
1817|			}
1818|		}
1819|		else if (*p == '$') {
1820|			*var_expand = true;
1821|		}
1822|		else if (*p == '\\') {
1823|			*need_unescape = true;
1824|			ucl_chunk_skipc(chunk, p);
1825|			if (p < chunk->end) {
1826|				ucl_chunk_skipc(chunk, p);
1827|			}
1828|			continue;
1829|		}
1830|
1831|		if (ucl_lex_is_atom_end(*p) || (chunk->remain >= 2 && ucl_lex_is_comment(p[0], p[1]))) {
1832|			break;
1833|		}
1834|		ucl_chunk_skipc(chunk, p);
1835|	}
1836|
1837|	return true;
