382|/**
383| * Check for a variable in a given string
384| * @param parser
385| * @param ptr
386| * @param remain
387| * @param out_len
388| * @param vars_found
389| * @return
390| */
391|static const char *
392|ucl_check_variable(struct ucl_parser *parser, const char *ptr,
393|				   size_t remain, size_t *out_len, bool *vars_found)
394|{
395|	const char *p, *end, *ret = ptr;
396|	bool found = false;
397|
398|	if (*ptr == '{') {
399|		/* We need to match the variable enclosed in braces */
400|		p = ptr + 1;
401|		end = ptr + remain;
402|		while (p < end) {
403|			if (*p == '}') {
404|				ret = ucl_check_variable_safe(parser, ptr + 1, p - ptr - 1,
405|											  out_len, true, &found);
406|				if (found) {
407|					/* {} must be excluded actually */
408|					ret++;
409|					if (!*vars_found) {
410|						*vars_found = true;
411|					}
412|				}
413|				else {
414|					*out_len += 2;
415|				}
416|				break;
417|			}
418|			p++;
419|		}
420|		if (p == end) {
421|			(*out_len)++;
422|		}
423|	}
424|	else if (*ptr != '$') {
425|		/* Not count escaped dollar sign */
426|		ret = ucl_check_variable_safe(parser, ptr, remain, out_len, false, &found);
427|		if (found && !*vars_found) {
428|			*vars_found = true;
429|		}
430|		if (!found) {
431|			(*out_len)++;
432|		}
433|	}
434|	else {
435|		ret++;
436|		(*out_len)++;
437|	}
438|
439|	return ret;
440|}
