1579|				if (!ucl_skip_comments(parser)) {
1580|					return false;
1581|				}
1582|				p = chunk->pos;
1583|			}
1584|			else if (ucl_test_character(*p, UCL_CHARACTER_WHITESPACE_UNSAFE)) {
1585|				ucl_chunk_skipc(chunk, p);
1586|			}
1587|			else if (ucl_test_character(*p, UCL_CHARACTER_KEY_START)) {
1588|				/* The first symbol */
1589|				c = p;
1590|				ucl_chunk_skipc(chunk, p);
1591|				*got_content = true;
1592|			}
1593|			else if (*p == '"') {
1594|				/* JSON style key */
1595|				c = p + 1;
1596|				got_quote = true;
1597|				*got_content = true;
1598|				ucl_chunk_skipc(chunk, p);
1599|			}
1600|			else if (*p == '}') {
1601|				/* We have actually end of an object */
1602|				*end_of_object = true;
1603|				return true;
1604|			}
1605|			else if (*p == '.' && !(parser->flags & UCL_PARSER_DISABLE_MACRO)) {
1606|				ucl_chunk_skipc(chunk, p);
1607|				parser->prev_state = parser->state;
1608|				parser->state = UCL_STATE_MACRO_NAME;
1609|				return true;
1610|			}
1611|			else {
1612|				/* Invalid identifier */
1613|				ucl_set_err(parser, UCL_ESYNTAX, "key must begin with a letter",
1614|							&parser->err);
1615|				return false;
1616|			}
1617|		}
1618|		else {
1619|			/* Parse the body of a key */
