1670|			}
1671|		}
1672|		else if (*p == ':') {
1673|			if (!got_eq && !got_semicolon) {
1674|				ucl_chunk_skipc(chunk, p);
1675|				got_semicolon = true;
1676|			}
1677|			else {
1678|				ucl_set_err(parser, UCL_ESYNTAX, "unexpected ':' character",
1679|							&parser->err);
1680|				return false;
1681|			}
1682|		}
