1747|		ucl_object_unref(nobj);
1748|		return false;
1749|	}
1750|	else if (keylen == 0) {
1751|		ucl_set_err(parser, UCL_ESYNTAX, "empty keys are not allowed", &parser->err);
1752|		ucl_object_unref(nobj);
1753|		return false;
1754|	}
1755|
1756|	nobj->key = key;
1757|	nobj->keylen = keylen;
1758|
1759|	if (!ucl_parser_process_object_element(parser, nobj)) {
1760|		return false;
1761|	}
1762|
1763|	if (ucl_escape) {
1764|		nobj->flags |= UCL_OBJECT_NEED_KEY_ESCAPE;
1765|	}
1766|
1767|
1768|	return true;
