1840|/**
1841| * Parse multiline string ending with \n{term}\n
1842| * @param parser
1843| * @param chunk
1844| * @param term
1845| * @param term_len
1846| * @param beg
1847| * @param var_expand
1848| * @return size of multiline string or 0 in case of error
1849| */
1850|static int
1851|ucl_parse_multiline_string(struct ucl_parser *parser,
1852|						   struct ucl_chunk *chunk, const unsigned char *term,
1853|						   int term_len, unsigned char const **beg,
1854|						   bool *var_expand)
1855|{
1856|	const unsigned char *p, *c, *tend;
1857|	bool newline = false;
1858|	int len = 0;
1859|
1860|	p = chunk->pos;
1861|
1862|	c = p;
1863|
1864|	while (p < chunk->end) {
1865|		if (newline) {
1866|			if (chunk->end - p < term_len) {
1867|				return 0;
1868|			}
1869|			else if (memcmp(p, term, term_len) == 0) {
1870|				tend = p + term_len;
1871|				if (tend < chunk->end && *tend != '\n' && *tend != ';' && *tend != ',') {
1872|					/* Incomplete terminator */
1873|					ucl_chunk_skipc(chunk, p);
1874|					continue;
1875|				}
1876|				len = p - c;
1877|				chunk->remain -= term_len;
1878|				chunk->pos = p + term_len;
1879|				chunk->column = term_len;
1880|				*beg = c;
1881|				break;
1882|			}
1883|		}
1884|		if (*p == '\n') {
1885|			newline = true;
1886|		}
1887|		else {
1888|			if (*p == '$') {
1889|				*var_expand = true;
1890|			}
1891|			newline = false;
1892|		}
1893|		ucl_chunk_skipc(chunk, p);
1894|	}
1895|
1896|	return len;
