1899|static inline ucl_object_t *
1900|ucl_parser_get_container(struct ucl_parser *parser)
1901|{
1902|	ucl_object_t *t, *obj = NULL;
1903|
1904|	if (parser == NULL || parser->stack == NULL || parser->stack->obj == NULL) {
1905|		return NULL;
1906|	}
1907|
1908|	if (parser->stack->obj->type == UCL_ARRAY) {
1909|		/* Object must be allocated */
1910|		obj = ucl_object_new_full(UCL_NULL, parser->chunks->priority);
1911|		t = parser->stack->obj;
1912|
1913|		if (!ucl_parser_account_node(parser)) {
1914|			ucl_object_unref(obj);
1915|			return NULL;
1916|		}
1917|
1918|		if (!ucl_array_append(t, obj)) {
1919|			ucl_object_unref(obj);
1920|			return NULL;
1921|		}
1922|
1923|		parser->cur_obj = obj;
1924|		ucl_attach_comment(parser, obj, false);
1925|	}
1926|	else {
1927|		/* Object has been already allocated */
1928|		obj = parser->cur_obj;
1929|	}
1930|
1931|	return obj;
