1953|		(ucl_test_character(*p, UCL_CHARACTER_WHITESPACE_UNSAFE) ||
1954|		(chunk->remain >= 2 && ucl_lex_is_comment(p[0], p[1])))) {
1955|		while (p < chunk->end && ucl_test_character(*p, UCL_CHARACTER_WHITESPACE_UNSAFE)) {
1956|			ucl_chunk_skipc(chunk, p);
1957|		}
1958|		if (!ucl_skip_comments(parser)) {
1959|			return false;
1960|		}
1961|		p = chunk->pos;
1962|	}
1963|
1964|	while (p < chunk->end) {
1965|		c = p;
1966|		switch (*p) {
1967|		case '"':
1968|			ucl_chunk_skipc(chunk, p);
1969|
1970|			if (!ucl_lex_json_string(parser, chunk, &need_unescape, &ucl_escape,
1971|									 &var_expand)) {
1972|				return false;
1973|			}
1974|
1975|			obj = ucl_parser_get_container(parser);
1976|			if (!obj) {
1977|				return false;
1978|			}
1979|
1980|			str_len = chunk->pos - c - 2;
1981|			obj->type = UCL_STRING;
1982|			if ((str_len = ucl_copy_or_store_ptr(parser, c + 1,
1983|												 &obj->trash_stack[UCL_TRASH_VALUE],
1984|												 &obj->value.sv, str_len,
1985|												 parser->limits.max_string_length,
1986|												 need_unescape, false,
1987|												 var_expand, false)) == -1) {
1988|				return false;
1989|			}
1990|
1991|			obj->len = str_len;
1992|			parser->state = UCL_STATE_AFTER_VALUE;
