1999|			if (!ucl_lex_squoted_string(parser, chunk, &need_unescape)) {
2000|				return false;
2001|			}
2002|
2003|			obj = ucl_parser_get_container(parser);
2004|			if (!obj) {
2005|				return false;
2006|			}
2007|
2008|			str_len = chunk->pos - c - 2;
2009|			obj->type = UCL_STRING;
2010|			obj->flags |= UCL_OBJECT_SQUOTED;
2011|
2012|			if ((str_len = ucl_copy_or_store_ptr(parser, c + 1,
2013|												 &obj->trash_stack[UCL_TRASH_VALUE],
2014|												 &obj->value.sv, str_len,
