3397|	chunk = parser->chunks;
3398|	if (chunk != NULL) {
3399|		parser->chunks = chunk->next;
3400|		ucl_chunk_free(chunk);
3401|		parser->recursion--;
3402|	}
3403|
3404|	parser->state = state;
3405|
3406|	return res;
